
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_c_sogga11_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_c_sogga11", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-1.105406110113213e-01, -1.132242604556193e-01, -1.172409187922322e-01, -1.232823845401715e-01, -1.323295018656392e-01, -1.454907768228131e-01, -1.629812618764079e-01, -1.809392766327065e-01, -1.879093840612195e-01, -1.795199971364818e-01, -1.535097650965666e-01, -4.473722404521639e-02, -5.855371176709444e-02, -3.829882143155527e-02, -4.564431093041998e-02, -6.439337575256852e-02, -7.954013990864160e-02, -7.601014925018876e-02, -2.442937771217247e-02, -3.512665053627466e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


